import {requireLogin} from './auth.js';
let user=null,settings={alerts_enabled:true,lottery_auto_refresh:true},loadedFor=null,loadVersion=0;
const dialog=document.createElement('dialog');dialog.className='settings-dialog';dialog.id='account-settings-dialog';dialog.setAttribute('aria-labelledby','settings-title');dialog.innerHTML='<div class="pref-inbox-heading"><h2 id="settings-title">账号设置</h2><button class="button secondary" type="button" data-settings-close aria-label="关闭设置">关闭</button></div><p id="settings-account"></p><form id="account-settings-form"><label class="settings-row"><span>启用账号偏好提醒<small>关闭后暂停生成新的偏好消息和微信推送，已保存条件与历史消息保留。</small></span><input type="checkbox" id="settings-alerts" checked></label><label class="settings-row"><span>抽签页面默认自动刷新<small>仅在抽签页可见时运行，约每60秒查询一次；离开页面后暂停。</small></span><input type="checkbox" id="settings-lottery-auto" checked></label><p id="settings-wechat"></p><p id="settings-status" role="status"></p><div class="pref-actions"><button class="button" type="submit" id="settings-save">保存设置</button><button class="button secondary" type="button" id="settings-watch">我的监控与消息</button></div></form>';document.body.append(dialog);
const $=s=>dialog.querySelector(s);
export function currentSettings(){return {...settings}}
function publish(){window.dispatchEvent(new CustomEvent('account-settings-changed',{detail:{...settings,loggedIn:!!user}}))}
async function load(){const version=++loadVersion,id=user?.id;if(!id)return;const response=await fetch('/api/user/settings',{signal:AbortSignal.timeout(15000)}),data=await response.json();if(!response.ok)throw Error(data.error||'读取失败');if(version!==loadVersion||user?.id!==id)return;settings=data.settings;loadedFor=id;publish();$('#settings-alerts').checked=settings.alerts_enabled;$('#settings-lottery-auto').checked=settings.lottery_auto_refresh;$('#settings-wechat').textContent=data.notificationReady?'微信模板通道已配置，需在具体偏好中单独开启。':'微信模板提醒尚未配置，站内消息可正常使用。'}
window.addEventListener('auth-changed',e=>{const next=e.detail.loggedIn?e.detail.user:null;if(next?.id===user?.id)return;user=next;loadVersion++;loadedFor=null;settings={alerts_enabled:true,lottery_auto_refresh:true};publish();if(!user){dialog.close();return}load().catch(()=>{})});
window.addEventListener('open-account-settings',async()=>{if(!await requireLogin())return;$('#settings-status').textContent='正在读取…';$('#settings-account').textContent='当前账号：'+(user?.nickname||'微信用户');dialog.showModal();$('#settings-save').disabled=true;try{await load();$('#settings-status').textContent='设置保存在账号中，登录其他设备后仍可使用。'}catch{$('#settings-status').textContent='读取失败，请关闭后重试。'}finally{$('#settings-save').disabled=loadedFor!==user?.id}});
dialog.querySelector('[data-settings-close]').onclick=()=>dialog.close();dialog.onclick=e=>{if(e.target===dialog)dialog.close()};$('#settings-watch').onclick=()=>{dialog.close();window.dispatchEvent(new CustomEvent('navigate-view',{detail:'watch'}))};
$('#account-settings-form').onsubmit=async e=>{e.preventDefault();const id=user?.id;if(!id)return;$('#settings-save').disabled=true;try{const response=await fetch('/api/user/settings',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({alerts_enabled:$('#settings-alerts').checked,lottery_auto_refresh:$('#settings-lottery-auto').checked}),signal:AbortSignal.timeout(15000)}),data=await response.json();if(user?.id!==id)return;if(!response.ok)throw Error(data.error||'保存失败');settings=data.settings;publish();$('#settings-status').textContent='设置已保存。'}catch(error){$('#settings-status').textContent=error.message}finally{$('#settings-save').disabled=false}};
